def transparent(run):
    run.font.name='Golos Text'; run.font.size=Pt(12); run.font.color.rgb=RGBColor(0,0,0)
    solid=run._r.get_or_add_rPr().find('{http://schemas.openxmlformats.org/drawingml/2006/main}solidFill')
    clr=solid[0]; alpha=etree.SubElement(clr,'{http://schemas.openxmlformats.org/drawingml/2006/main}alpha'); alpha.set('val','0')

def build(src,out,data):
    prs=Presentation(src)
    for no,text in data.items():
        for idx,block in enumerate(text.split('\n')):
            if not block.strip(): continue
            box=prs.slides[no-1].shapes.add_textbox(Inches(.35), Inches(.25+idx*.18), Inches(12.5), Inches(.25))
            box.name=f'EDITABLE OCR — slide {no} — block {idx+1}'
            box.text_frame.clear(); box.text_frame.margin_left=box.text_frame.margin_right=0
            r=box.text_frame.paragraphs[0].add_run(); r.text=block; transparent(r)
    prs.save(out)

for src,out,data in [('p1.pptx','p1_editable.pptx',P1),('p2.pptx','p2_editable.pptx',P2),('p3.pptx','p3_editable.pptx',P3)]: build(src,out,data)
